==> driver/vsim_filter.hpp <==
// Presentation filter for a cycle-accurate engine's raw output.
//
// `run --mode cycle` runs vsim standalone, which is chatty: it prints a startup
// banner (Copyright / Version) on stdout -- interleaved with the program's own
// stdout -- and verbose `[info]` log lines on stderr, including the headline
// "<N> cycles simulated" count. The user wants only the program's output and
// that count (restated as andesim's own one-line result), with vsim's banner
// and log hidden.
//
// VsimFilter classifies each output line, in arrival order, into drop / stdout /
// stderr, and lifts the cycle count out of the otherwise-hidden log so the
// driver can re-print it under its own [andesim] prefix. The logic is pure (no
// I/O); the spawn/relay loop that feeds it lives in process.cpp.
#ifndef ANDESIM_VSIM_FILTER_HPP
#define ANDESIM_VSIM_FILTER_HPP

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>

==> driver/models.hpp <==
// The three models andesim composes from engines. A model says *which*
// engines run and *how* they combine; the concrete engine(s) are resolved
// separately (built-in qemu, or a discovered verilator:<cfg>).
//
//   fast      = QEMU alone (functional), transparent passthrough.
//   cycle     = one Verilator alone, pure from reset, transparent passthrough.
//   hybrid    = QEMU fast-forwards, Verilator measures the ROI (+ a trigger).
#ifndef ANDESIM_MODELS_HPP
#define ANDESIM_MODELS_HPP

#include <string_view>

namespace andes_sim {

struct Model {
  std::string_view name;
  std::string_view engines;  // engine composition, for `list models`
  std::string_view notes;
};


==> driver/engine_registry.hpp <==
// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andesim rebuild.
//
// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
#ifndef ANDESIM_ENGINE_REGISTRY_HPP
#define ANDESIM_ENGINE_REGISTRY_HPP

#include <filesystem>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"

==> driver/hybrid.hpp <==
// The pure core of `run --mode hybrid`: turn the CLI selection into a Trigger.
//
// Split out from cmd_run.cpp so it is unit-testable without spawning qemu/vsim.
// pc-mode boundaries are resolved against the ELF .symtab here (via elf_syms),
// so the live path in cmd_run only has to build the 2-step plan and run it.
#ifndef ANDESIM_HYBRID_HPP
#define ANDESIM_HYBRID_HPP

#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

